insert into public.people (id, parent, name, name_ur, birth, birth_ur, death, death_ur, birthplace, birthplace_ur, residence, residence_ur, spouse, spouse_ur, notes, notes_ur, tag, locked, sort_order) values
  ('ali-hussain-rizvi', null, 'Mir Ali Hussain Rizvi', 'میر علی حسین رضوی', 'c. 1792–1793 (estimated)', 'تقریباً ۱۷۹۲–۱۷۹۳ء (تخمینی)', '', '', '', '', 'Lucknow', 'لکھنؤ', '', '', 'Earliest confirmed ancestor. Birth year estimated using a 30-year average generation gap back from Syed Hussain Ali Rizvi (b. 1882–1883) across three generations. The shajra dated the equivalent entry to c. 1650 AD, but the family understands that to have been a rough guess rather than a documented date, so the later estimate is treated as the better working figure.', 'سب سے قدیم مصدقہ جدِ امجد۔ سالِ پیدائش کا تخمینہ سید حسین علی رضوی (پیدائش ۱۸۸۲–۱۸۸۳ء) سے تین پشتیں پیچھے، فی پشت تیس سال کے اوسط کے حساب سے لگایا گیا ہے۔ شجرے میں اسی اندراج کی تاریخ تقریباً ۱۶۵۰ء درج ہے، مگر خاندان کے مطابق وہ محض ایک اندازہ تھا، کوئی دستاویزی تاریخ نہیں؛ اسی لیے بعد والے تخمینے کو بہتر عملی تاریخ سمجھا جاتا ہے۔', 'estimated', '{}', 0),
  ('ghulam-raza-rizvi-sr', 'ali-hussain-rizvi', 'Mir Ghulam Raza Rizvi', 'میر غلام رضا رضوی', '', '', '', '', '', '', 'Lucknow', 'لکھنؤ', '', '', 'Son of Mir Ali Hussain Rizvi. The family has confirmed the shajra''s generation order — Mir Ghulam Raza Rizvi comes before Syed Afzal Hussain Rizvi. An earlier family recollection had these two reversed.', 'میر علی حسین رضوی کے فرزند۔ خاندان نے شجرے میں دی گئی پشتوں کی ترتیب کی تصدیق کر دی ہے — میر غلام رضا رضوی، سید افضل حسین رضوی سے پہلے آتے ہیں۔ خاندان کی پہلی یاد میں یہ دونوں الٹ تھے۔', 'confirmed', '{}', 1),
  ('afzal-hussain-rizvi', 'ghulam-raza-rizvi-sr', 'Syed Afzal Hussain Rizvi', 'سید افضل حسین رضوی', '', '', '', '', '', '', 'Lucknow', 'لکھنؤ', 'Syeda Fatima Begum', 'سیدہ فاطمہ بیگم', 'Of Lucknow. Buried in Lucknow, consistent with the family''s residence in Mohalla Nakkhas. The Talkatora Karbala in that quarter is a plausible burial site but has not been confirmed.', 'لکھنؤ کے رہنے والے۔ لکھنؤ ہی میں مدفون ہیں، جو محلہ نکھاس میں خاندان کی رہائش سے مطابقت رکھتا ہے۔ اسی محلے کی تل کٹورہ کربلا ایک ممکنہ مدفن ہو سکتی ہے، مگر اس کی تصدیق نہیں ہوئی۔', 'confirmed', '{}', 2),
  ('hussain-ali-rizvi', 'afzal-hussain-rizvi', 'Syed Hussain Ali Rizvi', 'سید حسین علی رضوی', 'b. 1882–1883 (estimated)', 'پیدائش ۱۸۸۲–۱۸۸۳ء (تخمینی)', 'd. c. 1950', 'وفات تقریباً ۱۹۵۰ء', 'Lucknow', 'لکھنؤ', 'Lucknow, later Murshidabad', 'لکھنؤ، بعد ازاں مرشد آباد', 'Nowrozi Begum (3rd wife), b. 1912–1913 (estimated)', 'نوروزی بیگم (تیسری اہلیہ)، پیدائش ۱۹۱۲–۱۹۱۳ء (تخمینی)', 'A religious scholar and zakir. Birth year estimated from the family recollection that he was 45 at his marriage to Nowrozi Begum around 1927–1928; she was 15, giving her birth as 1912–1913. Separate family recollection puts him at approximately 1870–1880; the shajra says 1870.

He had three wives. His first wife, mother of Syed Ali Rizvi, passed away shortly after childbirth. He then married her sister, who also passed away shortly after her own childbirth — likely the mother of Yousuf Jahan, given her position in the birth order. Nowrozi Begum, the third wife and daughter of Sheikh Munawwar Ali, was the mother of the remaining children.

Moved from Lucknow to Murshidabad; the family recalls this was because his sister married into a Nawab family there whose title ended in "Jah". Owned property in Ikraam Ganj, Murshidabad, and refurbished a mosque there (name not yet recorded). Buried at a site the family calls Hussaini Dalan in Murshidabad. After he passed away around 1950 the family relocated to Dhaka around 1951.', 'عالمِ دین اور ذاکر۔ سالِ پیدائش کا تخمینہ خاندان کی اس یاد سے لگایا گیا ہے کہ نوروزی بیگم سے نکاح کے وقت، تقریباً ۱۹۲۷–۱۹۲۸ء میں، ان کی عمر ۴۵ برس تھی؛ نوروزی بیگم کی عمر ۱۵ برس تھی، جس سے ان کی پیدائش ۱۹۱۲–۱۹۱۳ء بنتی ہے۔ خاندان کی ایک الگ یاد کے مطابق ان کی پیدائش تقریباً ۱۸۷۰–۱۸۸۰ء کے درمیان ہے؛ شجرے میں ۱۸۷۰ء درج ہے۔

ان کی تین بیویاں تھیں۔ پہلی اہلیہ، جو سید علی رضوی کی والدہ تھیں، ولادت کے کچھ ہی عرصے بعد انتقال کر گئیں۔ اس کے بعد انہوں نے ان کی ہمشیرہ سے نکاح کیا (دوسری اہلیہ)، جو خود بھی اپنی ولادت کے کچھ عرصے بعد انتقال کر گئیں — ترتیبِ ولادت کے اعتبار سے غالباً وہی یوسف جہاں کی والدہ تھیں۔ تیسری اہلیہ نوروزی بیگم، جو شیخ منور علی کی صاحبزادی تھیں، باقی تمام اولاد کی والدہ تھیں۔

لکھنؤ سے مرشد آباد منتقل ہوئے؛ خاندان کو یاد ہے کہ اس کی وجہ یہ تھی کہ ان کی ہمشیرہ کی شادی وہاں کے ایک نوابی خاندان میں ہوئی تھی جس کے لقب کا اختتام "جاہ" پر ہوتا تھا۔ مرشد آباد میں اکرام گنج میں جائیداد کے مالک تھے اور وہاں ایک مسجد کی تجدید کرائی (نام ابھی درج نہیں)۔ مرشد آباد میں اس مقام پر مدفون ہیں جسے خاندان "حسینی دالان" کہتا ہے۔ تقریباً ۱۹۵۰ء میں ان کی وفات کے بعد خاندان تقریباً ۱۹۵۱ء میں ڈھاکہ منتقل ہو گیا۔', 'estimated', '{}', 3),
